/**
 * Self-contained Lights Out for the chat feed. Same contract as the other
 * games: createLightsOut({ onClose }) -> { element, focus, destroy }. The
 * starting board is generated by applying random presses to a solved board,
 * which guarantees it is always solvable.
 */

import { h } from '../../../core/dom.js';
import { t, tn } from '../../../core/i18n.js';
import { icon } from '../../icon.js';
import { readBest, writeBest } from './registry.js';

export const meta = { id: 'lightsout', name: t('game.name.lightsout'), icon: 'bulb' };

const SIZE = 5;
const SCRAMBLE = 8;
const BEST_KEY = 'of:gameLightsOut:best';

/**
 * @param {{ onClose?: () => void }} [opts]
 * @returns {{ element: HTMLElement, focus: () => void, destroy: () => void }}
 */
export function createLightsOut(opts = {}) {
  const N = SIZE * SIZE;
  let grid, moves, solved;
  let best = readBest(BEST_KEY);

  function flip(i) {
    grid[i] = !grid[i];
    const r = Math.floor(i / SIZE), c = i % SIZE;
    if (r > 0) grid[i - SIZE] = !grid[i - SIZE];
    if (r < SIZE - 1) grid[i + SIZE] = !grid[i + SIZE];
    if (c > 0) grid[i - 1] = !grid[i - 1];
    if (c < SIZE - 1) grid[i + 1] = !grid[i + 1];
  }

  function allOff() {
    return grid.every((on) => !on);
  }

  function reset() {
    grid = new Array(N).fill(false);
    moves = 0;
    solved = false;
    // Scramble from the solved state so the puzzle is always solvable.
    do {
      for (let k = 0; k < SCRAMBLE; k++) flip(Math.floor(Math.random() * N));
    } while (allOff());
  }

  function press(i) {
    if (solved) return;
    flip(i);
    moves++;
    if (allOff()) {
      solved = true;
      if (best === 0 || moves < best) { best = moves; writeBest(BEST_KEY, best); }
    }
    render();
  }

  function restart() {
    reset();
    render();
    element.focus();
  }

  // --- DOM ---------------------------------------------------------------

  const movesEl = h('b', {}, '0');
  const bestEl = h('b', {}, best ? String(best) : '·');
  const overlayEl = h('div', { className: 'chat-game__overlay' });

  const boardEl = h('div', {
    className: 'chat-game__board chat-game__board--lights',
    style: { gridTemplateColumns: `repeat(${SIZE}, 1fr)` },
  });
  const cells = [];
  for (let i = 0; i < N; i++) {
    const idx = i;
    const cell = h('button', {
      className: 'lights-cell', type: 'button', 'aria-label': t('game.tile'),
      onClick: () => press(idx),
    });
    cells.push(cell);
    boardEl.appendChild(cell);
  }

  const title = h('span', { className: 'chat-game__title' }, [
    h('span', { className: 'chat-game__title-icon', innerHTML: icon('bulb') }),
    meta.name,
  ]);
  const restartBtn = h('button', {
    className: 'chat-game__icon-btn', title: t('game.newGame'), 'aria-label': t('game.newGame'),
    innerHTML: icon('rotate-ccw'), onClick: restart,
  });
  const closeBtn = h('button', {
    className: 'chat-game__icon-btn', title: t('game.closeGame'), 'aria-label': t('game.closeGame'),
    innerHTML: icon('x'),
    onClick: () => { teardown(); if (opts.onClose) opts.onClose(); },
  });

  const header = h('div', { className: 'chat-game__header' }, [
    title,
    h('div', { className: 'chat-game__scores' }, [
      h('div', { className: 'chat-game__score' }, [h('span', {}, t('game.moves')), movesEl]),
      h('div', { className: 'chat-game__score' }, [h('span', {}, t('game.best')), bestEl]),
    ]),
    h('div', { className: 'chat-game__actions' }, [restartBtn, closeBtn]),
  ]);

  const stage = h('div', { className: 'chat-game__stage' }, [boardEl, overlayEl]);
  const hint = h('div', { className: 'chat-game__hint' }, t('game.hint.lightsout'));
  const element = h('div', { className: 'chat-game', tabindex: '0' }, [header, stage, hint]);

  function render() {
    for (let i = 0; i < N; i++) {
      cells[i].className = `lights-cell${grid[i] ? ' lights-cell--on' : ''}`;
    }
    movesEl.textContent = String(moves);
    bestEl.textContent = best ? String(best) : '·';

    if (solved) {
      overlayEl.style.display = '';
      overlayEl.replaceChildren(
        h('div', { className: 'chat-game__overlay-title' }, tn('game.clearedIn', moves)),
        h('button', { className: 'chat-game__overlay-btn', onClick: restart }, t('game.playAgain')),
      );
    } else {
      overlayEl.style.display = 'none';
      overlayEl.replaceChildren();
    }
  }

  // Idempotent so the close button and host cleanup can both call it safely.
  let destroyed = false;
  function teardown() {
    if (destroyed) return;
    destroyed = true;
    element.remove();
  }

  reset();
  render();

  return {
    element,
    focus: () => element.focus(),
    destroy: teardown,
  };
}
